// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, createHighlight, updateHighlight, putHighlight, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "name": "Highlights Patch Rejections"
    }`;

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 511
        },
        "name": "Highlights Patch Rejection Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/hl-patch-reject"
    }`;

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "yellow",
        "comment": "original note",
        "endOffset": 17,
        "linkId": 522,
        "startOffset": 0,
        "text": "Rejection passage"
    }`;

    // Request Body
    const highlightsHighlightsPatchRequestBody: string = `{
        "color": "blue"
    }`;

    // Request Body
    const highlightsHighlightsPatch1RequestBody: string = `{
        "text": "not an updatable field"
    }`;

    // Request Body
    const highlightsHighlightsPatch2RequestBody: string = `{
        "color": "purple"
    }`;

    // Request Body
    const highlights999999999PatchRequestBody: string = `{
        "color": "red"
    }`;

    // Request Body
    const highlightsHighlightsPutRequestBody: string = `{
        "color": "yellow",
        "comment": "method not allowed probe"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {"collection.id": getResponseValue(collectionsPostResponse, "response.id")});
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const highlightsPostResponse = await createHighlight(client, URL_localhost, headers, highlightsPostRequestBody, {"linkId": getResponseValue(linksPostResponse, "response.id")});
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    const highlightId = getResponseValue(highlightsPostResponse, "response.id");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Highlights Patch Rejections");
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Highlights Patch Rejection Source");
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'created colour').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'created comment').toBe("original note");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'created text').toBe("Rejection passage");

    const highlightsHighlightsPatchResponse = await updateHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPatchRequestBody);
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.id"), 'the accepted patch reached this highlight').toBe(highlightId);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.color"), 'accepted colour').toBe("blue");

    const highlightsHighlightsPatch1Response = await updateHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPatch1RequestBody, 400);
    expect(highlightsHighlightsPatch1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response"), 'a body naming neither colour nor comment is refused').toBe("Error: Provide a color or a comment to update []");

    const highlightsHighlightsPatch2Response = await updateHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPatch2RequestBody, 400);
    expect(highlightsHighlightsPatch2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsHighlightsPatch2Response, "response"), 'a colour outside the four is refused').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");

    const highlights999999999PatchResponse = await updateHighlight(client, URL_localhost, headers, "999999999", highlights999999999PatchRequestBody, 404);
    expect(highlights999999999PatchResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(highlights999999999PatchResponse, "response"), 'an id this caller has no highlight for').toBe("Highlight not found.");

    const abcPatchResponse = await updateHighlight(client, URL_localhost, headers, "abc", highlights999999999PatchRequestBody, 400);
    expect(abcPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcPatchResponse, "response"), 'an id that is not a number').toBe("Please choose a valid highlight.");

    const highlightsHighlightsPutResponse = await putHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPutRequestBody);
    expect(highlightsHighlightsPutResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(highlightsHighlightsPutResponse, "response"), 'unimplemented method is answered').toBe("Method not allowed.");

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link').toBe(getResponseValue(linksPostResponse, "response.id"));
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
});
